    for change in diff.iter_all_changes() {
        let sign = match change.tag() {
            ChangeTag::Delete => "-",
            ChangeTag::Insert => "+",
            ChangeTag::Equal => " ",
        };
        diff_str.push_str(&format!("{sign}{change}"));
    }

    write_file_atomically(&target, new_file_content.as_bytes(), &base_canon)?;

    Ok(EditFileResult {
        path: args.path,
        replacements: count,
        diff: diff_str,
    })
}

